using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Roles.Impostor;using TownOfHost.Roles.AddOns.Common;
class Program{static int passed;static void Check(bool b,string m){if(!b)throw new Exception(m);}static (Experiencer e,PlayerControl me) Setup(){OptionItem.Items.Clear();Experiencer.RoleInfo.Setup();AmongUsClient.Instance.AmHost=true;GameStates.IsInTask=true;GameStates.IsMeeting=false;GameStates.IsLobby=false;GameStates.IsFreePlay=false;Options.CurrentGameMode=CustomGameMode.Standard;Amnesia.Allow=true;var me=new PlayerControl{PlayerId=1};var e=new Experiencer(me);me.Active=e;me.Data.PlayerId=1;e.Add();me.Data.Tasks.Add(new(){Id=7});PlayerControl.LocalPlayer=me;PlayerControl.Players[1]=me;PlayerState.States[1]=new();Utils.Messages.Clear();UtilsNotifyRoles.Calls=0;return(e,me);}static int Points(Experiencer e)=>int.Parse(e.GetProgressText().Split('(')[1].Split(')')[0]);static void Test(string n,Action a){Setup();a();passed++;Console.WriteLine("PASS "+n);}
static void Main(){
Test("actual task event patch reaches the role and emits private progress",()=>{var me=PlayerControl.LocalPlayer;TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==5&&Utils.Messages.Count==1&&Utils.Messages.All(m=>m.Target==1),"event hook");Check(UtilsNotifyRoles.Calls==1&&RoleBase.LastRpc[0].Equals(5),"display and RPC");});
Test("repeated task event cannot award duplicate points",()=>{var me=PlayerControl.LocalPlayer;TaskCompleteAdapter.Prefix(me,7);TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==5,"repeat");});
Test("invented task ID does not award points",()=>{var me=PlayerControl.LocalPlayer;TaskCompleteAdapter.Prefix(me,99);Check(Points(me.Active)==0,"invalid task");});
Test("nonhost event cannot mutate authoritative points",()=>{var me=PlayerControl.LocalPlayer;AmongUsClient.Instance.AmHost=false;TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==0,"client event");});
Test("blocked role ability cannot gain task points",()=>{var me=PlayerControl.LocalPlayer;Amnesia.Allow=false;TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==0,"blocked");});
Test("Shell task flag is true for play and false for crew victory",()=>{var me=PlayerControl.LocalPlayer;Check(UtilsTask.HasTasks(me.Data,false),"local task flag");Check(!UtilsTask.HasTasks(me.Data,true),"crew task count");});
Test("console prefix delegates to native code rather than granting use",()=>{var me=PlayerControl.LocalPlayer;float distance=99;bool can,could;bool runNative=ConsoleAdapter.Prefix(ref distance,new FakeConsole{AllowImpostor=false},me.Data,out can,out could);Check(runNative&&!can&&!could,"prefix forced native permission");});
Test("TaskBattle uses its own early return without Experiencer points",()=>{var me=PlayerControl.LocalPlayer;Options.CurrentGameMode=CustomGameMode.TaskBattle;TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==0,"special mode");});
Test("MurderMystery uses its own early return without Experiencer points",()=>{var me=PlayerControl.LocalPlayer;Options.CurrentGameMode=CustomGameMode.MurderMystery;TaskCompleteAdapter.Prefix(me,7);Check(Points(me.Active)==0,"special mode");});
Console.WriteLine($"RESULT {passed} passed, 0 failed");}}
